///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkNumFormat
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @param {*} len len
 * @returns {void}
 * @hidden N
 */
scwin.checkNumFormat = function (obj, len) { try { if (!obj || obj.getValue() === null) { return; } const v = String(obj.getValue()); const neg = v.charAt(0) === '-' ? '-' : ''; const parts = v.replace(/[^\d.]/g, '').split('.'); let i = parts.shift() || ''; let d = parts.join(''); d = (len > 0) ? d.substring(0, len) : ''; i = i.replace(/^0+(?=\d)/, ''); let f = ''; while (i.length > 3) { f = ',' + i.slice(-3) + f; i = i.slice(0, -3); } obj.setValue(neg + i + f + (d ? '.' + d : '')); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name etnChangePage
 * @description etn Change Page 처리
 * @param {*} tab tab
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnChangePage = async function (tab) {
    form = (document.etnListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_readDataVO').get('lastSaveStatCd'));
    if (lastSaveStatCdInt === 0 && tab > 1) {
        await $c.win.alert('발행증권에 관한 사항을 먼저 저장해주세요.');
        return;
    } else {
        if (lastSaveStatCdInt === 1 && tab > 2) {
            await $c.win.alert('발행증권2(손실제한)에 관한 사항을 먼저 저장해주세요.');
            return;
        } else {
            if (lastSaveStatCdInt === 2 && tab > 3) {
                await $c.win.alert('발행회사에 관한 사항을 먼저 저장해주세요.');
                return;
            } else {
                if (lastSaveStatCdInt === 3 && tab > 4) {
                    await $c.win.alert('보증인/제3자LP에 관한 사항을 먼저 저장해주세요.');
                    return;
                }
            }
        }
    }
    if (tab === 1) {
        $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewIsuTab');
    } else {
        if (tab === 2) {
            return;
        } else {
            if (tab === 3) {
                $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewIsurTab');
            } else {
                if (tab === 4) {
                    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewSrtyLpTab');
                } else {
                    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewAttachFileTab');
                }
            }
        }
    }
    form.action = 'LossLimitEtnList.do';
    await scwin.tx_fn_EtnChangePage();
};

